package com.ruoyi.web.controller.shop;
import java.util.*;import java.io.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.*;import com.ruoyi.common.core.domain.AjaxResult;
@RestController @RequestMapping("/shop/admin/reports") @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:finance')") public class ShopReportsController {
 @Autowired ShopReports reports;@Autowired ShopService s;
 @GetMapping("/products") public AjaxResult products(){return AjaxResult.success(s.jdbc().queryForList("select id,name,spec from shop_product order by sort_order,id"));}
 @GetMapping("/grades") public AjaxResult grades(){return AjaxResult.success(reports.gradeOptions());}
 @GetMapping public AjaxResult data(@RequestParam String from,@RequestParam String to,@RequestParam(defaultValue="all")String channel,@RequestParam(defaultValue="false")boolean includeTests,@RequestParam(defaultValue="-1")int tier,@RequestParam(defaultValue="0")long productId,@RequestParam(defaultValue="all")String identity,@RequestParam(defaultValue="all")String businessType){return AjaxResult.success(reports.data(from,to,channel,includeTests,tier,productId,identity,businessType));}
 @GetMapping("/export") public ResponseEntity<byte[]> export(@RequestParam String from,@RequestParam String to,@RequestParam(defaultValue="all")String channel,@RequestParam(defaultValue="false")boolean includeTests,@RequestParam(defaultValue="-1")int tier,@RequestParam(defaultValue="0")long productId,@RequestParam(defaultValue="all")String identity,@RequestParam(defaultValue="all")String businessType)throws IOException{Map<String,Object> data=reports.data(from,to,channel,includeTests,tier,productId,identity,businessType);try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){String[][] definitions={{"memberGrowth","会员注册增长","day:注册日期","registered:新增注册会员","cumulative:截至当日注册会员"},{"teamRanking","团队销售排行","rank:排名","memberId:团队归属会员编号","name:团队归属会员","orders:付款订单数","paid:付款分","refunded:退款分","net:净额分"},{"teamUnattributed","未归属团队销售","name:归属说明","orders:付款订单数","paid:付款分","refunded:退款分","net:净额分"},{"withdrawals","提现申请","id:申请编号","nickname:分销员","amount:申请金额分","fee:手续费分","status:当前状态","created_at:申请时间","occurred_at:实际到账时间"},{"legacyCommissions","旧版佣金","id:记录编号","nickname:分销员","order_no:订单号","channel:渠道","amount:金额分","status:当前状态","created_at:创建时间"},{"days","每日趋势","name:日期","paid:付款分","refunded:退款分","net:净额分","orders:付款订单数"},{"channels","渠道对比","name:渠道","paid:付款分","refunded:退款分","net:净额分","orders:付款订单数"},{"modes","付款方式","name:付款方式","paid:付款分","refunded:退款分","net:净额分"},{"products","商品排行","productId:商品编号","name:商品名称规格","channel:渠道","quantity:当期净件数","paid:商品付款分","refunded:商品退款分","net:商品净额分"},{"customers","客户排行","name:客户","channel:渠道","orders:付款订单数","paid:付款分","refunded:退款分","net:净额分"},{"commissions","分销变动","member_id:分销员编号","nickname:分销员","generated_change:佣金变动分","available_change:可提变动分"},{"bank","对公核验","kind:收退类型","amount:金额分","unallocated:其中未归商品分"},{"events","订单收退明细","order_no:订单号","business_type:订单类型","partner_tier_name:成交档位","channel:渠道","kind:收退类型","mode:付款方式","is_test:测试标记","occurred_at:发生时间","selectedAmount:筛选范围内金额分"}};for(String[] definition:definitions){Sheet sheet=wb.createSheet(definition[1]);Row head=sheet.createRow(0);for(int j=2;j<definition.length;j++){head.createCell(j-2).setCellValue(definition[j].split(":")[1]);sheet.setColumnWidth(j-2,24*256);}int row=1;for(Object obj:(Collection<?>)data.get(definition[0])){Map<?,?> item=(Map<?,?>)obj;Row r=sheet.createRow(row++);for(int j=2;j<definition.length;j++){Object value=item.get(definition[j].split(":")[0]);if(value instanceof Number)r.createCell(j-2).setCellValue(((Number)value).doubleValue());else r.createCell(j-2).setCellValue(value==null?"":String.valueOf(value));}}sheet.createFreezePane(0,1);}Sheet note=wb.createSheet("口径说明");note.createRow(0).createCell(0).setCellValue(String.valueOf(data.get("basis")));note.createRow(1).createCell(0).setCellValue("日期："+from+" 至 "+to+"；渠道："+channel+"；当前等级序号："+tier+"；商品编号："+productId+"；订单类型："+businessType+"；客户身份："+identity+"；包含测试："+includeTests+"；金额以整数分导出，除以100为元。");note.setColumnWidth(0,100*256);wb.write(out);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).header("Content-Disposition","attachment; filename=reports.xlsx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(out.toByteArray());}}
}
